WITH not_flagged AS (SELECT s.* FROM suppliers s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.product_name NOT LIKE '%wirele%')) SELECT city, STDDEV_SAMP(rating) AS rating_stddev, COUNT(CASE WHEN city = 'Bangkok' THEN 1 END) AS bangkok_count, COUNT_IF(city = 'Singapore') AS singapore_events, SORT_ARRAY(COLLECT_SET(city)) AS city_list FROM not_flagged GROUP BY city HAVING singapore_events >= 1 ORDER BY city DESC NULLS LAST;
